window.BUCH = {"content":{"name":"[Ihr Vorname]","musik":{"lautstaerke":0.5},"cover":{"titel":"Happy Birthday\nMarie","untertitel":"Band 27","bild":"cover.jpg","fokus":"60% 30%","chat":[{"von":"ich","text":"Welches Buch ist das?"},{"von":"sie","text":"[Ihre Antwort aus dem ersten Chat]"},{"von":"ich","text":"[Deine Antwort]"}]},"widmung":{"text":["Für die einzige Person, die mir sagen konnte, welches Buch das ist.","Auch wenn es keins war."]},"prolog":{"label":"Prolog","titel":"Ein zufälliges Zitat","seiten":[["Manche Geschichten beginnen in einer Buchhandlung. Manche auf einer Party. Diese hier beginnt mit einem Video, in dem ein Buch zu sehen war. Oder genauer: in dem ich *dachte*, ein Buch zu sehen.","Da war dieser eine Satz: [das Zitat aus dem Video]. Klang nach einem Roman, den man gelesen haben muss. Also tat ich, was jeder vernünftige Mensch tun würde, und schrieb einer völlig Fremden:","#chat"],["Die Antwort war so kurz wie vernichtend: gar keins. Es war ein Zitat. [Von wem/woher das Zitat stammte.]","Ich hatte also ein Gespräch mit der Frage nach einem Buch begonnen, das es nicht gibt. Kein Einstieg, den man in Ratgebern findet.","Aber wer viel liest, weiß: Die besten Geschichten fangen selten so an, wie man es erwartet. Und manchmal beginnen sie einfach mit einem kleinen Missverständnis."]]},"kapitel":{"label":"Kapitel 27","titel":"Die Hauptfigur","intro":["Jede gute Geschichte braucht eine Hauptfigur. Diese hier liest schneller, als andere Leute Klappentexte überfliegen, und hat eine Meinung zu jedem Buch. Meistens die richtige.","Es folgen einige Aufnahmen aus dem Archiv. Beweisstücke, sozusagen."],"fotos":[{"bild":"1.jpg","fokus":"44% 50%","text":"[Unterschrift, z. B.: Die Hauptfigur in ihrem natürlichen Lebensraum.]"},{"bild":"2.jpg","fokus":"50% 30%","text":"[Unterschrift, z. B.: Streng, aber fair. Wie ihre Buchkritiken.]"},{"bild":"3.jpg","text":"[Unterschrift, z. B.: Hier noch ahnungslos, dass sie bald in einem Buch landet.]"},{"bild":"4.jpg","text":"[Unterschrift]"}]},"epilog":{"label":"Epilog","titel":"Alles Gute","text":["Band 27 also. Die Kritik ist sich einig: Die Reihe wird mit jedem Teil besser, und niemand rechnet damit, dass ihr die Ideen ausgehen.","Ich wünsche dir ein Jahr voller guter Bücher, noch besserer Tage und genug ruhiger Abende, um beides zu genießen. Und falls du mal nicht weißt, was du als Nächstes lesen sollst: Ich kenne jemanden, der sehr gerne danach fragt.","Alles Gute zum Geburtstag, [Ihr Vorname]!"],"gruss":"[Dein Name]"},"anhang":{"label":"Anhang","titel":"Ein Brief für dich","hinweis":"Zum Öffnen antippen","umschlag":"Für dich","brief":{"anrede":"Liebe [Ihr Vorname],","text":["eigentlich schenkt man einer Leserin ein Buch. Aber nach unserem Start traue ich mir bei der Frage, welches, ehrlich gesagt nicht mehr ganz über den Weg.","Deshalb etwas für die Leseabende drumherum: Tee, Kerze, Handcreme für die vielen Seiten. Du entscheidest."],"gutschein":{"titel":"dm-Gutschein","wert":"[Betrag] €","code":"[CODE]","buttonText":"Code kopieren","kopiertText":"Kopiert"},"gruss":"[Dein Name]"}},"rueckseite":{"klappentext":"Eine Geschichte, die mit einem Zitat beginnt, das kein Buch war. Mit einer Frage, die eigentlich eine ganz andere Antwort verdient hätte. Und mit einer Hauptfigur, die man nach den ersten Seiten nicht mehr so leicht aus der Hand legt.","rezensionen":[{"text":"Überraschend gut für einen 27. Band.","quelle":"Das Feuilleton"},{"text":"Hätte ich schon viel früher lesen sollen.","quelle":"Ein aufmerksamer Leser"}],"isbn":"ISBN 01-10-1999"},"ui":{"blaetternHinweis":"Wischen oder tippen"}},"images":{"cover.jpg":"data:image/jpeg;base64,","1.jpg":"data:image/jpeg;base64,","2.jpg":"data:image/jpeg;base64,","3.jpg":null,"4.jpg":null},"hasAudio":false};
